    "托管服务拒绝了合并。请确认你拥有写入权限、所需检查均已通过，并且分支没有冲突。",
  "The host refused it. Check that you have write access to this repository.":
    "托管服务拒绝了操作。请确认你拥有此仓库的写入权限。",
  "The host refused it. Check that you have write access, or that you opened it.":
    "托管服务拒绝了操作。请确认你拥有写入权限，或此请求由你创建。",
  "The host refused it. Check that you have write access, and that the branch still exists.":
    "托管服务拒绝了操作。请确认你拥有写入权限且分支仍然存在。",
  // oxlint-disable-next-line t3code/no-em-dash-copy -- Exact upstream strings are translation lookup keys.
  "The host refused it. Check that you have write access to the branch — one from a fork also needs its author to allow edits from maintainers — and that it does not conflict with the base.":
    "托管服务拒绝了操作。请确认你拥有该分支的写入权限；来自复刻仓库的分支还需作者允许维护者编辑，并确保它与基础分支没有冲突。",
  "The host refused it. Check that this repository allows auto-merge, that you have write access, and that there is something left for it to wait on.":
    "托管服务拒绝了操作。请确认仓库允许自动合并、你拥有写入权限，并且仍有条件需要等待。",
  "The host refused it. Check that you have write access, and that the merge has not already happened.":
    "托管服务拒绝了操作。请确认你拥有写入权限，并且合并尚未完成。",
  "The host refused it. Check that you have write access and that this pull request was merged on the host.":
    "托管服务拒绝了操作。请确认你拥有写入权限，并且此拉取请求已在托管服务中合并。",
  "The host refused it. Check that you have Actions write access and that these workflow runs are still awaiting approval.":
    "托管服务拒绝了操作。请确认你拥有 Actions 写入权限，并且这些工作流运行仍在等待批准。",
  "The host refused it. A rebase stops at the first commit that does not apply cleanly; updating with a merge commit may still work.":
    "托管服务拒绝了操作。变基会在首个无法干净应用的提交处停止；使用合并提交更新仍可能成功。",
