  "The environment's server signs in to Expo and starts the sessions. Without a token here it uses EXPO_TOKEN, then its eas login.":
    "由环境所在服务器登录 Expo 并启动会话。未在此填写令牌时，优先使用 EXPO_TOKEN，其次使用 eas 登录状态。",
